#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Buffs.Level;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Difficulties;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.reverseSatellite)]
    public class ReverseSatellite : AIEntityBehaviour
    {
        public ReverseSatellite(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            var buff = entity.AddBuff<FlyBuff>();
            buff.SetProperty(FlyBuff.PROP_TARGET_HEIGHT, 80f);

            entity.Level.AddLoopSoundEntity(VanillaSoundID.morseCodeReverse, entity.ID);

            SetLeaveTimer(entity, new FrameTimer(LEAVE_TIME));

            entity.Velocity = new Vector3(entity.RNG.Next(-1f, 1f), 0, entity.RNG.Next(-1f, 1f));
        }
        protected override void UpdateAI(Entity enemy)
        {
            base.UpdateAI(enemy);
            if (!enemy.Level.HasBuff<ReverseSatelliteBuff>())
            {
                enemy.Level.AddBuff<ReverseSatelliteBuff>();
            }
            if (!IsLeft(enemy))
            {
                var leavingTimer = GetLeaveTimer(enemy);
                if (leavingTimer.RunToExpiredOrNull() || enemy.Level.WaveState == VanillaLevelStates.STATE_AFTER_FINAL_WAVE || enemy.Level.IsAllEnemiesCleared())
                {
                    SetLeft(enemy, true);
                }
            }

            switch (enemy.State)
            {
                case STATE_STAY:
                    UpdateStateWalk(enemy);
                    break;
                case STATE_LEAVE:
                    UpdateStateLeaving(enemy);
                    break;
            }
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            entity.RemoveBuffs<FlyBuff>();
        }
        public override void PostContactGround(Entity entity, Vector3 velocity)
        {
            base.PostContactGround(entity, velocity);
            if ((entity.IsDead || entity.IsAIFrozen()) && entity.IsAboveLand())
            {
                float damageMutliplier = entity.Level.GetReverseSatelliteDamageMultiplier();
                float radius = entity.GetRange();
                var damage = entity.GetDamage() * damageMutliplier;
                if (damage >= 0)
                {
                    entity.Explode(entity.GetCenter(), radius, entity.GetFaction(), damage, new DamageEffectList(VanillaDamageEffects.EXPLOSION));
                }
                Explosion.Spawn(entity, entity.GetCenter(), entity.GetScaledSize());
                entity.PlaySound(VanillaSoundID.explosion);

                entity.Remove();
            }
        }
        private void UpdateStateWalk(Entity enemy)
        {
            var pos = enemy.Position;
            var velocity = enemy.Velocity;
            var centerX = LevelPositions.LAWN_CENTER_X;
            var centerZ = enemy.Level.GetLawnCenterZ();
            var backDistanceX = 200;
            var backDistanceZ = 80;
            if (pos.x > centerX + backDistanceX)
            {
                if (velocity.x > -3)
                {
                    velocity.x -= 0.1f;
                }
            }
            else if (pos.x < centerX - backDistanceX)
            {
                if (velocity.x < 3)
                {
                    velocity.x += 0.1f;
                }
            }
            if (pos.z > centerZ + backDistanceZ)
            {
                if (velocity.z > -3)
                {
                    velocity.z -= 0.1f;
                }
            }
            else if (pos.z < centerZ - backDistanceZ)
            {
                if (velocity.z < 3)
                {
                    velocity.z += 0.1f;
                }
            }
            var magnitude = velocity.magnitude;
            magnitude += 0.05f;
            enemy.Velocity = velocity.normalized * magnitude;
        }
        private void UpdateStateLeaving(Entity enemy)
        {
            var velocity = enemy.Velocity;
            if (velocity.x < 6)
            {
                velocity.x += 0.1f;
            }
            enemy.Velocity = velocity;

            var pos = enemy.Position;
            if (pos.x > LevelPositions.RIGHT_BORDER || pos.y > 640f || pos.z < -40f)
            {
                enemy.Remove();
            }
        }
        public static FrameTimer? GetLeaveTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(FIELD_LEAVE_TIMER);
        public static void SetLeaveTimer(Entity entity, FrameTimer value) => entity.SetBehaviourField(FIELD_LEAVE_TIMER, value);
        public static bool IsLeft(Entity entity) => entity.GetBehaviourField<bool>(FIELD_LEFT);
        public static void SetLeft(Entity entity, bool value) => entity.SetBehaviourField(FIELD_LEFT, value);
        public const int STATE_STAY = LogicEnemyStates.WALK;
        public const int STATE_LEAVE = LogicEnemyStates.LEAVE;
        public const int LEAVE_TIME = 900;
        public static readonly VanillaEntityPropertyMeta<bool> FIELD_LEFT = new VanillaEntityPropertyMeta<bool>("is_left");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> FIELD_LEAVE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("LeaveTimer");
    }
}
